window.kbPageData["views/entry/k-13180bbfd51c959f"] = {"key":"entry/k-13180bbfd51c959f","state":{"route":"entry/k-13180bbfd51c959f"},"node":{"id":"k-13180bbfd51c959f","mode":"k","title":"全民阅读推广与服务","type":"概念与词义","domain":"文化","reading":"","intro":"","priority":100,"aliases":["完善全民阅读推广服务体系"],"qs":["江苏 2024 A类 申论#2","江苏 2024 A类 申论#4"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"tags":{"专题":["culture"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["文化"],"来源主题":["就业、社保与公共服务"],"资料类别":["非时政"]},"directorySummary":"全民阅读推广通过荐书、读书会等活动吸引公众参与阅读，培养阅读兴趣和习惯。全民阅读服务通过公共阅读空间、阅读资源和无障碍设施等，为不同人群提供参与阅读的条件。","review":{"title":"全民阅读推广与服务","type":"概念与词义","definition":"全民阅读推广通过荐书、读书会等活动吸引公众参与阅读，培养阅读兴趣和习惯。全民阅读服务通过公共阅读空间、阅读资源和无障碍设施等，为不同人群提供参与阅读的条件。","explanation":"图书馆和社区可以结合读书活动与日常服务，既吸引读者参与，也方便读者持续阅读。公益阅读推广着重分享和普及阅读，直播售书以销售图书为直接目的，讲书和荐书可以同时发挥两种作用。《“十四五”规划纲要》提出深入推进全民阅读、建设书香中国。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"江苏 2024 A类 申论#2":"对照资料5和6，按活动宗旨、服务对象和运作方式归纳阅读推广与直播售书中出现的问题。","江苏 2024 A类 申论#4":"结合首届全民阅读大会贺信和资料8，论证阅读习惯如何养成、公共阅读服务如何支持公众参与。"}},"aspects":[{"title":"公益阅读推广与直播售书","uses":[{"unit":"Q1","role":"直接考查","use":"本题依据资料5和资料6辨析两类活动。图书馆早期亲子阅读活动名额紧张，反映活动供给有限。直播讲书可以兼具阅读分享和促销作用，材料也提到直播渠道出现低价盗版书的问题。","evidence":"“给定资料5-6”中提到的“阅读推广”与“阅读推销”是现实生活中的常见现象，这两类现象涉及哪些问题？请围绕这些问题谈谈你的认识。","qids":["江苏 2024 A类 申论#2"]}]},{"title":"全民阅读倡导与公共服务","uses":[{"unit":"Q2","role":"解题依据","use":"本题以首届全民阅读大会贺信中的倡导为立意依据。党员干部带头读书、儿童养成阅读习惯、全社会共同参与，分别体现了不同群体的参与方式。资料8中的公共图书馆免费开放、农家书屋和读书节可用于论述阅读设施和推广活动如何支持公众参与。","evidence":"修身养志，增长才干；希望孩子们养成阅读习惯，快乐阅读，健康成长","qids":["江苏 2024 A类 申论#4"]}]}],"sources":[{"id":"4d94680ab5558551","label":"完善全民阅读推广服务体系","topic":"就业、社保与公共服务","category":"非时政","text":"2.完善全民阅读推广服务体系\n全民阅读促进工作坚持中国共产党的领导，坚持以习近平新时代中国特色社会主义思想\n为指导，贯彻落实习近平文化思想，坚持以人民为中心，坚定文化自信，发展社会主义先进\n文化，弘扬革命文化，传承中华优秀传统文化。\n全民阅读促进工作坚持以社会主义核心价值观为引领，传播有益于公民全面发展和社会\n文明进步的科学文化知识，激发公民阅读兴趣，培养公民阅读习惯，增强公民阅读能力，提\n升公民阅读质量，形成全社会爱读书、读好书、善读书的浓厚氛围。\n全民阅读促进工作由党委领导、政府主导、社会力量参与，按照公益性、基本性、均等\n性、便利性的要求，构建全民覆盖、普惠高效的全民阅读促进体系，涵育文明风尚，厚植家\n国情怀，增强实现中华民族伟大复兴的精神力量。\n每年 4 月第四周为全民阅读活动周。\n——《全民阅读促进条例》","source":{"doc":"6cbfb01fe723bba64b75","first":44,"last":44,"page":44,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"江苏 2024 A类 申论#2":{"paper":"江苏 2024 A类 申论","n":2,"mod":"申论","src":["4fbf1d8260d6665235b0.pdf",4],"asrc":["411b0576fd3fd921b344.pdf",1],"card":"870e5c7bcc39bf0974d29378","links":[{"id":"k-13180bbfd51c959f","role":"直接考查","why":"活动供给不足和宣传覆盖有限会制约推广的持续性和影响力，改进需兼顾活动供给与传播方式。"}]},"江苏 2024 A类 申论#4":{"paper":"江苏 2024 A类 申论","n":4,"mod":"申论","src":["4fbf1d8260d6665235b0.pdf",4],"asrc":["411b0576fd3fd921b344.pdf",2],"card":"40eea5e8e98a464910ac1a64","links":[{"id":"k-13180bbfd51c959f","role":"解题依据","why":"参考文章用制度保障、公共阅读设施和多样服务说明推广全民阅读的具体条件。"}]}},"terms":{},"references":{},"topics":[{"slug":"culture","title":"文化传承与创新表达"}],"units":{"k-13180bbfd51c959f":[["江苏 2024 A类 申论#2"],["江苏 2024 A类 申论#4"]]}};
